'use client'

import * as React from 'react'

// One player is rendered by `identity` and never by this file: the avatar
// cases, the signed-out case and the accessible name are decided there. This
// card owns the band, the tail and the four card states, and nothing else.
import { Identity, type IdentityPlayer } from './identity'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled PlayerCard, and `tsc --noEmit` passes on it,
// so the gate cannot catch it.
import './player-card.css'

/**
 * PlayerCard: one pickable player, as a card.
 *
 * The anatomy is fixed by specimen 3k and is what makes it a card rather than a
 * tile: a modifier band across the top, a portrait, the player's name, a meta
 * line, and a tail. The band and the tail are this component's; the portrait,
 * the name and the meta line are an `identity`, rendered by `identity`.
 *
 * It performs nothing. It does not decide whether a pick is allowed, does not
 * settle a result and does not know what a player is worth. The host owns the
 * card's state and hands it over; a press is reported and nothing more.
 *
 * Four states, which are the four the specimen draws: idle, selected,
 * committed, and settled. Selected is reversible and committed is not, and a
 * settled card carries `data-gs-state` with the result. Each changes the fill
 * or the stroke, a glyph and the accessible name together, never the colour on
 * its own.
 */

/** The three settled results, from the attribute contract's three-things rule. */
export type PlayerCardState = 'correct' | 'wrong' | 'rewarded'

export interface PlayerCardProps
  extends Omit<React.HTMLAttributes<HTMLElement>, 'children' | 'onSelect'> {
  /**
   * Who the card is for. `null` is the signed-out case, which `identity`
   * renders; a card for a slot nobody has filled is a real state a host shows.
   */
  player: IdentityPlayer | null
  /** The team the card stands for, when it stands for one. Rides `data-gs-team`. */
  team?: string
  /**
   * The band across the top: what picking this player is worth, in the host's
   * own words. "+1 Assist", "Captain", "Double points".
   */
  modifier?: React.ReactNode
  /** The line under the name: club, number, position. Passed to `identity`. */
  meta?: React.ReactNode
  /** The tail under the card: the fixture, the kick-off, the odds. */
  detail?: React.ReactNode
  /** Picked, not yet committed. Reversible. */
  selected?: boolean
  /** Locked in. No longer reversible. */
  committed?: boolean
  /** How it settled, once the host knows. */
  state?: PlayerCardState
  /** Available later, not now. Keeps its shape and shows a padlock. */
  locked?: boolean
  /** Not available at all. */
  disabled?: boolean
  /** The name to announce, when the host has a better one than the player's. */
  label?: string
  /**
   * Makes the card the control that picks the player. Without it the card is a
   * rendering and the host's own button does the picking, which is what
   * specimen 3k draws.
   */
  onSelect?: (playerId: string | undefined) => void
}

/**
 * The words that go with the states. Taken from `choice`, because a card and an
 * option are the same four states and two vocabularies for them is how a
 * screen reader user ends up with two games.
 */
const STATE_WORD: Record<string, string> = {
  selected: 'selected',
  committed: 'locked in',
  correct: 'correct',
  wrong: 'wrong',
  rewarded: 'rewarded',
}

/** Inline SVG taking `currentColor`, so a glyph is a glyph in every theme. */
function Glyph({ state }: { state: PlayerCardState | 'locked' }) {
  const common = {
    width: 14,
    height: 14,
    viewBox: '0 0 16 16',
    fill: 'none',
    stroke: 'currentColor',
    strokeWidth: 2.4,
    strokeLinecap: 'round' as const,
    strokeLinejoin: 'round' as const,
    'aria-hidden': true,
  }
  if (state === 'correct') return <svg {...common}><path d="M3 8.5l3.5 3.5L13 4.5" /></svg>
  if (state === 'wrong') return <svg {...common}><path d="M4 4l8 8M12 4l-8 8" /></svg>
  if (state === 'rewarded')
    return (
      <svg {...common}>
        <path d="M8 2.5l1.8 3.7 4 .6-2.9 2.8.7 4-3.6-1.9-3.6 1.9.7-4L2.2 6.8l4-.6z" />
      </svg>
    )
  return (
    <svg {...common}>
      <rect x="3.5" y="7" width="9" height="6.5" rx="1.5" />
      <path d="M5.5 7V5.2a2.5 2.5 0 0 1 5 0V7" />
    </svg>
  )
}

export function PlayerCard({
  player,
  team,
  modifier,
  meta,
  detail,
  selected = false,
  committed = false,
  state,
  locked = false,
  disabled = false,
  label,
  onSelect,
  className,
  ...rest
}: PlayerCardProps) {
  // Committed wins over selected: a card the player locked in is not still
  // waiting to be picked, and two markers saying so would leave a host
  // deciding which one it believed.
  const picked = committed ? 'committed' : selected ? 'selected' : undefined
  const unavailable = disabled || locked

  // The name carries every state, because a screen reader user gets no fill, no
  // stroke and no glyph. Order: who it is, what picking them is worth, then
  // what is true of the card.
  const words = [label ?? player?.displayName ?? (player === null ? 'Guest' : 'Player')]
  if (typeof meta === 'string') words.push(meta)
  if (typeof modifier === 'string') words.push(modifier)
  if (picked) words.push(STATE_WORD[picked] as string)
  if (state) words.push(STATE_WORD[state] as string)

  const glyph = state ?? (locked ? 'locked' : undefined)

  const body = (
    <>
      {/* The band renders for a settled or locked card even with no modifier,
          because the glyph is how the result reaches a player who cannot tell
          the two fills apart. */}
      {modifier === undefined && glyph === undefined ? null : (
        <span
          className="gs-player-card__band gs-action-type"
          data-gs-scope="player-card"
          data-gs-part="label"
          aria-hidden="true"
        >
          {glyph === undefined ? null : (
            // The glyph is emphasis: it appears with the state and does not
            // move, so a player on reduced motion still gets the answer.
            <span
              className="gs-player-card__glyph"
              data-gs-scope="player-card"
              data-gs-part="glyph"
              data-gs-animates="emphasis"
            >
              <Glyph state={glyph} />
            </span>
          )}
          {modifier}
        </span>
      )}
      {/* The portrait, the name and the meta line, all of them identity's. This
          file writes no avatar and no name of its own. */}
      <Identity player={player} size="large" aria-hidden="true">
        {meta}
      </Identity>
      {detail === undefined ? null : (
        <span className="gs-player-card__tail" data-gs-scope="player-card" data-gs-part="detail" aria-hidden="true">
          {detail}
        </span>
      )}
    </>
  )

  const attributes = {
    className: ['gs-player-card', onSelect ? 'gs-pressable' : null, className]
      .filter(Boolean)
      .join(' '),
    'data-gs-component': 'player-card',
    'data-gs-player': player?.id,
    'data-gs-team': team,
    'data-gs-selected': picked === 'selected' ? ('true' as const) : undefined,
    'data-gs-committed': picked === 'committed' ? ('true' as const) : undefined,
    'data-gs-state': state,
    'data-gs-locked': locked ? ('true' as const) : undefined,
    'data-gs-disabled': disabled ? ('true' as const) : undefined,
    'aria-label': words.join(', '),
  }

  if (onSelect === undefined) {
    return (
      <div {...rest} {...attributes} role="group">
        {body}
      </div>
    )
  }

  return (
    <button
      {...rest}
      {...attributes}
      type="button"
      // The card moves on press, so it is motion and stops dead under reduced
      // motion. Its fill, stroke and glyph are emphasis and survive.
      data-gs-animates="motion"
      aria-pressed={picked !== undefined}
      aria-disabled={unavailable || undefined}
      disabled={disabled}
      onClick={() => {
        if (unavailable || committed) return
        onSelect(player?.id)
      }}
    >
      {body}
    </button>
  )
}

/* Player card. Every value comes from a token; nothing here is a literal colour.
 *
 * The press gesture and the action type come from the shared rule sets in
 * `app/gamestage-primitives.css`, which ships with `@gamestage/tokens`. Import
 * that file at your root beside the token stylesheet, or a pressable card will
 * not move and the band will not take the theme's action face.
 */

.gs-player-card {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  inline-size: 100%;
  /* Every card the same height, whatever it holds. Without this the card takes
     its height from its contents: a long fixture line, a two-line band or a
     missing detail each moved it, and eleven cards came out at five sizes. The
     detail area takes up the slack rather than the card changing shape. */
  block-size: 100%;
  padding: 0;
  overflow: hidden;
  text-align: center;

  background: var(--gs-color-surface);
  color: var(--gs-color-ink);
  border: var(--gs-stroke-control) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-lg);
  box-shadow: var(--gs-depth-raised);

  font-family: var(--gs-type-body-font-family);
}

/* The card is a control only when the host gave it something to do, so the
   cursor and the focus ring follow the element rather than the class. */
button.gs-player-card {
  cursor: pointer;
}

/* The plain class selector, as `button`, `choice`, `reward` and `selector` all
   write it. A type-qualified `button.gs-player-card:focus-visible` did not take
   effect in the lab at all, and stage 8 caught it: the card rendered
   identically focused and unfocused, so a keyboard user could not see where
   focus was. */
.gs-player-card:focus-visible {
  outline: var(--gs-stroke-focus) solid var(--gs-color-ink);
  outline-offset: var(--gs-space-1);
}

/* -- the band -------------------------------------------------------------- */
/* What picking this player is worth. It is the top edge of the card, which is
   what specimen 3k uses to tell a card from a tile. */
/* The band holds one line, always.

   It wrapped, and a wrapped band makes a taller card, so a row of cards came out
   at five different heights: "Opens at kick-off" and "Pick a player" each took
   two lines while "+1 goal" took one. A grid of cards is read as a grid, and a
   card that is 23px taller than its neighbour reads as broken before anybody
   works out which one moved. Long copy is truncated with its full text still in
   the accessible name. */
.gs-player-card__band {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--gs-space-2);
  block-size: var(--gs-size-action);
  padding: var(--gs-space-1) var(--gs-space-3);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;

  background: var(--gs-color-edge);
  color: var(--gs-color-ink-secondary);
}

.gs-player-card__glyph {
  display: inline-flex;
  align-items: center;
  /* Emphasis, not motion: the glyph changes colour with the state and never
     moves, so it survives reduced motion. */
  transition: color var(--gs-motion-emphasis) ease-out;
}

/* -- the player ------------------------------------------------------------ */
/* Identity renders the portrait, the name and the meta line. The card only
   turns its row into a column and lets the portrait fill the card's width. */
/* The portrait runs edge to edge, the words are inset.

   It used to be the other way round: the band was full width and the portrait
   sat inside a space-3 margin with its own rounded corners and border, so the
   card had two competing rectangles and three different left edges, and the
   portrait read as a picture pinned to a card rather than as the card. A player
   card is a portrait with a band over it and a name under it, which is one
   object.

   The portrait is also no longer square. A square eats the card: at 11rem wide
   it took 176px of a 270px card and left the name, the club and the fixture
   fighting over what was left. 4 by 5 is the proportion a squad card is drawn
   at and it gives the words room. */
.gs-player-card [data-gs-component='identity'] {
  flex-direction: column;
  align-items: stretch;
  gap: 0;
  padding: 0;
  inline-size: 100%;
}

.gs-player-card [data-gs-scope='identity'][data-gs-part='avatar'] {
  inline-size: 100%;
  block-size: auto;
  aspect-ratio: 4 / 5;
  border-radius: 0;
  border: 0;
  object-fit: cover;
}

/* The words under the portrait, as one block with one inset. */
.gs-player-card [data-gs-scope='identity'][data-gs-part='label'],
.gs-player-card [data-gs-scope='identity'][data-gs-part='detail'] {
  padding-inline: var(--gs-space-3);
  text-align: center;
}

.gs-player-card [data-gs-scope='identity'][data-gs-part='label'] {
  padding-top: var(--gs-space-3);
}

.gs-player-card [data-gs-scope='identity'][data-gs-part='detail'] {
  font-size: var(--gs-type-label-font-size);
  color: var(--gs-color-ink-secondary);
}

/* -- the tail -------------------------------------------------------------- */
.gs-player-card__tail {
  padding: 0 var(--gs-space-3) var(--gs-space-3);
  font-size: var(--gs-type-label-font-size);
  line-height: var(--gs-type-body-line-height);
  color: var(--gs-color-ink-secondary);
}

/* -- selected: reversible -------------------------------------------------- */
/* Stroke and weight together, never colour alone. */
.gs-player-card[data-gs-selected='true'] {
  border-color: var(--gs-color-selected);
  border-width: var(--gs-stroke-selected);
}

/* -- committed: not reversible --------------------------------------------- */
.gs-player-card[data-gs-committed='true'] {
  border-color: var(--gs-color-interactive-base);
  border-width: var(--gs-stroke-selected);
}

.gs-player-card[data-gs-committed='true'] .gs-player-card__band {
  background: var(--gs-color-interactive);
  color: var(--gs-color-on-accent);
}

/* -- settled: fill or stroke, glyph, text ---------------------------------- */
.gs-player-card[data-gs-state='correct'] .gs-player-card__band {
  background: var(--gs-color-positive);
  color: var(--gs-color-on-bright);
}

.gs-player-card[data-gs-state='correct'] {
  border-color: var(--gs-color-positive-base);
}

.gs-player-card[data-gs-state='wrong'] {
  border-style: dashed;
  border-color: var(--gs-color-negative);
}

.gs-player-card[data-gs-state='wrong'] .gs-player-card__band {
  color: var(--gs-color-negative);
  text-decoration: line-through;
}

.gs-player-card[data-gs-state='rewarded'] {
  border-color: var(--gs-color-reward-base);
  box-shadow: var(--gs-depth-reward);
}

.gs-player-card[data-gs-state='rewarded'] .gs-player-card__band {
  background: var(--gs-color-reward);
  color: var(--gs-color-on-bright);
}

/* -- locked and disabled --------------------------------------------------- */
/* Locked keeps its shape and shows a padlock. Only disabled goes flat. */
.gs-player-card[data-gs-locked='true'] {
  cursor: not-allowed;
}

.gs-player-card[data-gs-disabled='true'] {
  background: var(--gs-color-disabled);
  color: var(--gs-color-disabled-ink);
  box-shadow: var(--gs-depth-flat);
  cursor: not-allowed;
}
